from machine import I2C,UART,Pinfrom  Sengo1  import *import timeimport random# 等待Sengo1完成操作系统的初始化。此等待时间不可去掉，避免出现Sengo1尚未初始化完毕主控器已经开发发送指令的情况time.sleep(2)# 选择UART或者I2C通讯模式，Sengo1出厂默认为I2C模式，短按模式按键可以切换# 4种UART通讯模式：UART9600（标准协议指令），UART57600（标准协议指令），UART115200（标准协议指令），Simple9600（简单协议指令），# 参看“简单协议指令”# https://tosee.readthedocs.io/zh/latest/Common/Protocol/index.html#section-6########################################################################################################## port = UART(2,rx=Pin(16),tx=Pin(17),baudrate=9600)port = I2C(1,scl=Pin(22),sda=Pin(21),freq=400000)# Sengo1通讯地址：0x60。如果I2C总线挂接多个设备，请避免出现地址冲突sengo1 = Sengo1(0x60)err = sengo1.begin(port)if err != SENTRY_OK:    print(f"Initialization failed，error code:{err}")else:    print("Initialization succeeded")# 利用随机数从6组预设代码中选取一组参数并赋值给算法index = (random.randint(1, 6))print("random = %d"%index)if (index == 1):  sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 6, 6, color_label_e.kColorBlack], 1)  # 等待新参数生效后的识别结果产出，该时间间隔不得低于该算法识别1帧所花费的时间，可以通过算法开启后，屏幕下方的帧率进行推算  time.sleep(0.1)if (index == 2):  sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 6, 6, color_label_e.kColorWhite], 1)  time.sleep(0.1)if (index == 3):  sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 6, 8, color_label_e.kColorRed], 1)  time.sleep(0.1)if (index == 4):  sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 8, 6, color_label_e.kColorGreen], 1)  time.sleep(0.1)if (index == 5):  sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 8, 8, color_label_e.kColorBlue], 1)  time.sleep(0.1)if (index == 6):  sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 8, 6, color_label_e.kColorYellow], 1)  time.sleep(0.1)# 1、参考文档# https://tosee.readthedocs.io/zh/latest/Sentry1/Vision/index.html#chapter-vs1-vision-blob-index# 2、参考视频（注：Sengo1与Sentry1是两款产品）# https://www.bilibili.com/video/BV1924y157UD/?spm_id_from=333.1387.upload.video_card.click&vd_source=a6a4a13d17ed26ee248472534a8ec3cc# 3、色块检测算法常见的应用场景：分拣与搬运不同颜色的物体；巡线，包括常见的白底黑线地图以及模拟道路的地图# 4、Sengo1每次只能运行一种识别算法# 5、正常使用时，应由主控板发送指令控制Sengo1的算法开启关闭，而不是通过Sengo1的摇杆进行操作；err = sengo1.VisionBegin(sengo1_vision_e.kVisionBlob)if err != SENTRY_OK:    print(f"Starting algo Blob failed，error code:{err}")else:    print("Starting algo Blob succeeded")while True:    # Sengo1不主动返回检测识别结果，需要主控板发送指令进行读取。读取的流程：首先读取识别结果的数量，接收到指令后，Sengo1会刷新结果数据，如果结果数量不为零，那么主控再发送指令读取结果的相关信息。请务必按此流程构建程序。    obj_num = sengo1.GetValue(sengo1_vision_e.kVisionBlob, sentry_obj_info_e.kStatus)    if obj_num:        x = sengo1.GetValue(sengo1_vision_e.kVisionBlob, sentry_obj_info_e.kXValue)        y = sengo1.GetValue(sengo1_vision_e.kVisionBlob, sentry_obj_info_e.kYValue)        w = sengo1.GetValue(sengo1_vision_e.kVisionBlob, sentry_obj_info_e.kWidthValue)        h = sengo1.GetValue(sengo1_vision_e.kVisionBlob, sentry_obj_info_e.kHeightValue)                if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorBlack):          print("Black")        if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorWhite):          print("White")        if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorRed):          print("Red")        if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorGreen):          print("Green")        if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorBlue):          print("Blue")        if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorYellow):          print("Yellow")                  print("x=%d, y=%d, w=%d, h=%d"%(x, y, w, h))        time.sleep(0.2)        print("\n")    